\label{cov-th}
For any $t_1,t_2>0$,
\begin{equation}
\label{def-K}
K(t_1,t_2):=\lim_{R \to \infty}\frac{1}{R^{\gamma}}\mathbb{E}[F_R(t_1) F_R(t_2)] \quad \mbox{is finite},
\end{equation}
where
\begin{equation}
\label{def-gamma}
\gamma:=\left\{
\begin{array}{ll} d & \mbox{in case (i)} \\
2d-\beta & \mbox{in case (ii) }.
\end{array} \right.
\end{equation}
In particular, $\sigma_R^2(t) \sim K(t,t) R^{\gamma}$ as $R \to \infty$, for any $t>0$.

\label{lemG*G}
Let $d\in \{1,2\}$. For any $t,s>0$ and $x\in \mathbb{R}^d$, we have:
\begin{equation}
\label{G*G}
(G_t*G_s)(x)=\frac{1}{2}\int_{|t-s|}^{t+s} G_{\theta}(x) d\theta.
\end{equation}

We show that both sides have the same Fourier transforms. On the left side,
\begin{align*}
\mathcal{F}(G_t*G_s)(\xi)&= \mathcal{F} G_t(\xi)\mathcal{F} G_s(\xi)=\frac{\sin(t|\xi|) \sin(s|\xi|)}{|\xi|^2}.
\end{align*}
On the right side,
\begin{align*}
\frac{1}{2}\int_{|t-s|}^{t+s} \mathcal{F} G_{\theta}(\xi) d\theta=\frac{1}{2}\int_{|t-s|}^{t+s} \frac{\sin(\theta|\xi|)}{|\xi|} d\theta=\frac{\cos\big(|t-s||\xi|\big)- \cos \big( (t+s)|\xi|\big)}{2|\xi|^2}.
\end{align*}

If $u \in \mathbb{L}^{1,2}$, $\{D_{t,x}u(s,y)\}_{(s,y)} \in {\rm Dom}(\delta)$ for almost all $(t,x)$, and there exists a measurable modification of $\{\int D_{t,x}u(s,y)W(\delta s,\delta y)\}_{(t,x)}$ which is in $L^2(\Omega;\mathcal{H})$, then $\delta(u) \in \mathbb{D}^{1,2}$ and the following identity holds, 
\begin{equation}
\label{Heisenberg}
D(\delta(u))=u+\delta(Du).
\end{equation}

For any $F \in \mathbb{D}^{1,2}$ and $\varphi \in C^1(\mathbb{R})$ with $\varphi'$ bounded,
\begin{equation}
\label{chain}
D\varphi(F)=\varphi'(F)DF.
\end{equation}

For any $F,G \in \mathbb{D}^{1,2}$,
\begin{equation}
\label{Poincare}
|{\rm Cov}(F,G)| \leq \int_{\mathbb{R}_+} \int_{\mathbb{R}^{2d}} \|D_{r,y}F \|_2 \|D_{r,y'}G\|_2 f(y-y') dydy'dr.
\end{equation}

\label{ergodicity}
Let $\{Z(t,x) : t \geq 0,\ x \in \mathbb{R}^d \}$ be an adapted random field such that $\{ Z(t,x)\}_{x \in \mathbb{R}^d}$ is strictly stationary, and $Z(t,x) \in \mathbb{D}^{1,2}$ for any $t \geq 0$ and $x \in \mathbb{R}^d$. Assume that for any $0 < r < t$ and $x,z \in \mathbb{R}^d$,
\begin{equation}\label{DZ}
\| D_{r,z}Z(t,x)\|_2 \leq C_t G_{t-r}(x-z)
\end{equation}
where $C_t > 0$ is a constant that depends on $t$. Then $\{ Z(t,x)\}_{x \in \mathbb{R}^d}$ is ergodic.

